export interface ParseContext {
  today: Date;
  /** True when the text names one of the board's columns. */
  isColumn: (text: string) => boolean;
  /** True when the text names someone on the board (or "me"). */
  isPerson: (text: string) => boolean;
}

const clean = (s: string) => s.trim().replace(/^["'“”‘’]+|["'“”‘’]+$/g, '').trim();

/** Splits "<title> due friday to doing for Riya" into the title and its trailing clauses. */
function splitClauses(text: string, ctx: ParseContext) {
  let rest = text;
  const out: { column?: string; due?: string; assignee?: string } = {};
  const kw = /\s+(due|by|on|to|into|in|for|assigned to|assign to|assign it to)\s+/gi;

  for (let guard = 0; guard < 5; guard++) {
    const matches = [...rest.matchAll(kw)];
    if (matches.length === 0) break;
    let accepted = false;
    // Try the clause closest to the end first.
    for (let i = matches.length - 1; i >= 0; i--) {
      const m = matches[i];
      const word = m[1].toLowerCase();
      const value = clean(rest.slice((m.index ?? 0) + m[0].length));
      if (!value) continue;
      let ok = false;
      if (['due', 'by', 'on'].includes(word) && !out.due && parseDue(value, ctx.today)) {
        out.due = value;
        ok = true;
      } else if (['to', 'into', 'in'].includes(word) && !out.column && ctx.isColumn(value)) {
        out.column = value;
        ok = true;
      } else if (word.startsWith('assign') && !out.assignee) {
        out.assignee = value;
        ok = true;
      } else if (word === 'for' && !out.assignee && ctx.isPerson(value)) {
        out.assignee = value;
        ok = true;
      }
      if (ok) {
        rest = rest.slice(0, m.index);
        accepted = true;
      }
      break; // only the last clause can be peeled off each round
    }
    if (!accepted) break;
  }
  return { title: clean(rest), ...out };
}

/** Finds the last " to <column>" split, so card titles may themselves contain "to". */
function splitAtColumn(text: string, ctx: ParseContext): { card: string; column: string } | null {
  const re = /\s+(?:to|into|onto|in|over to)\s+/gi;
  const ms = [...text.matchAll(re)];
  for (let i = ms.length - 1; i >= 0; i--) {
    const m = ms[i];
    const column = clean(text.slice((m.index ?? 0) + m[0].length));
    if (ctx.isColumn(column)) return { card: clean(text.slice(0, m.index)), column };
  }
  if (ms.length === 0) return null;
  const last = ms[ms.length - 1];
  return { card: clean(text.slice(0, last.index)), column: clean(text.slice((last.index ?? 0) + last[0].length)) };
}

/**
 * Understands plain-language commands, typed or spoken. Works offline with no AI service,
 * so it is fast, private and predictable.
 */
export function parseCommand(raw: string, ctx: ParseContext): Command {
  const text = raw.trim().replace(/[.!?]+$/, '').replace(/\s+/g, ' ');
  const orig = text
    .replace(/^(?:(?:please|hey handrail|handrail|ok|okay|can you|could you)[, ]+)+/i, '')
    .replace(/[, ]+please$/i, '');
  const t = orig.toLowerCase();

  if (!t) return { type: 'unknown', text: raw };
  if (/^(undo|undo that|take that back|oops)$/.test(t)) return { type: 'undo' };
  if (/^(redo|redo that)$/.test(t)) return { type: 'redo' };
  if (/^(help|what can i (say|do)|commands|\?)$/.test(t)) return { type: 'help' };
  if (/^(summary|summarise|summarize|status|overview|where am i|read (the )?board|read everything|read all|what'?s on the board)$/.test(t))
    return { type: 'summary' };
  if (/^(what('?s| has| is)? (changed|new)|changes|show changes|what did (they|people|the team) change|catch me up|whats new)$/.test(t))
    return { type: 'changes' };
  if (/^(what'?s|what is|whats|show|list|read)? ?(mine|my (cards|tasks|stuff|work)|assigned to me|what do i have|what am i doing)$/.test(t))
    return { type: 'mine' };

  let m = t.match(/^(?:what'?s|what is|whats|show|list|read|anything)?\s*(overdue|late)(?: cards| tasks)?$/);
  if (m) return { type: 'whatsDue', range: 'overdue' };
  m = t.match(/^(?:what'?s|what is|whats|show|list|read|anything)?\s*(?:cards |tasks |stuff )?due\s*(today|tomorrow|this week|soon|next|)$/);
  if (m) {
    const w = m[1];
    return { type: 'whatsDue', range: w === 'today' ? 'today' : w === 'tomorrow' ? 'tomorrow' : w ? 'week' : 'all' };
  }

  m = orig.match(/^(?:add|create|make|new)\s+(?:a\s+)?(?:new\s+)?(?:column|list|lane)\s+(?:called\s+|named\s+)?(.+)$/i);
  if (m) return { type: 'addColumn', title: clean(m[1]) };

  m = orig.match(/^(?:add|create|make|new|remind me to)\s+(?:a\s+)?(?:new\s+)?(?:card|task|item)?\s*(?:called\s+|named\s+|to\s+)?(.+)$/i);
  if (m && !/^(note|notes)\b/i.test(m[1])) {
    const c = splitClauses(m[1], ctx);
    if (c.title) return { type: 'add', ...c };
  }

  m = orig.match(/^(?:add\s+(?:a\s+)?note|note)\s+(?:to|on)\s+(.+?)\s*:\s*(.+)$/i);
  if (m) return { type: 'note', card: clean(m[1]), text: m[2].trim() };

  m = orig.match(/^rename\s+(.+?)\s+(?:to|as)\s+(.+)$/i);
  if (m) return { type: 'rename', card: clean(m[1]), title: clean(m[2]) };

  m = orig.match(/^(?:move|put|send|drag|shift|bump)\s+(.+?)\s+(up|down)(?:\s+one)?$/i);
  if (m) return { type: 'nudge', card: clean(m[1]), direction: m[2].toLowerCase() as 'up' | 'down' };

  m = orig.match(/^(?:move|put|send|drag|shift|bump)\s+(.+?)\s+(?:to|at)\s+(?:the\s+)?(top|bottom|start|end)(?:\s+of\s+(.+))?$/i);
  if (m) {
    const pos = /top|start/i.test(m[2]) ? 'top' : 'bottom';
    return { type: 'move', card: clean(m[1]), column: m[3] ? clean(m[3]) : undefined, position: pos };
  }

  m = orig.match(/^(?:move|put|send|drag|shift)\s+(.+)$/i);
  if (m) {
    let body = m[1];
    let position: 'top' | 'bottom' | undefined;
    const pm = body.match(/\s+(?:at|to|on)\s+(?:the\s+)?(top|bottom|start|end)$/i);
    if (pm) {
      position = /top|start/i.test(pm[1]) ? 'top' : 'bottom';
      body = body.slice(0, pm.index);
    }
    const split = splitAtColumn(body, ctx);
    if (split) return { type: 'move', card: split.card, column: split.column, position };
  }

  m = orig.match(/^mark\s+(.+?)\s+(?:as\s+)?(done|finished|complete|completed)$/i)
    ?? orig.match(/^(?:done with|done|finished|finish|complete|completed|tick off|check off|close)\s+(.+)$/i)
    ?? orig.match(/^(.+?)\s+is\s+(?:done|finished|complete|completed)$/i)
    ?? orig.match(/^(?:i\s+)?(?:finished|completed|did)\s+(.+)$/i);
  if (m) return { type: 'done', card: clean(m[1]) };

  m = orig.match(/^mark\s+(.+?)\s+as\s+(.+)$/i);
  if (m) return { type: 'move', card: clean(m[1]), column: clean(m[2]) };

  m = orig.match(/^(?:start|begin|start on|work on|working on|i'?m working on|i am working on)\s+(.+)$/i);
  if (m) return { type: 'start', card: clean(m[1]) };

  m = orig.match(/^(?:delete|remove|trash|archive|get rid of)\s+(.+)$/i);
  if (m) return { type: 'delete', card: clean(m[1]) };

  m = orig.match(/^(?:unassign|clear (?:the )?assignee (?:of|on|for))\s+(.+)$/i);
  if (m) return { type: 'assign', card: clean(m[1]), person: null };

  m = orig.match(/^(?:assign|give)\s+(.+?)\s+to\s+(.+)$/i);
  if (m) return { type: 'assign', card: clean(m[1]), person: clean(m[2]) };

  m = orig.match(/^(?:clear|remove) (?:the )?due date (?:of|on|for|from)\s+(.+)$/i);
  if (m) return { type: 'due', card: clean(m[1]), due: null, dueText: '' };

  m = orig.match(/^(?:set\s+)?(?:the\s+)?due date (?:of|on|for)\s+(.+?)\s+(?:to|as|is)\s+(.+)$/i)
    ?? orig.match(/^(?:set\s+)?(.+?)\s+(?:is\s+)?due\s+(.+)$/i);
  if (m) {
    const due = parseDue(m[2], ctx.today);
    if (due) return { type: 'due', card: clean(m[1]), due, dueText: m[2] };
  }

  m = orig.match(/^(?:read|what'?s in|what is in|whats in|list|show|open)\s+(?:the\s+)?(.+?)(?:\s+(?:column|list|lane))?$/i);
  if (m) {
    const target = clean(m[1]);
    if (ctx.isColumn(target)) return { type: 'read', target };
    return { type: 'readCard', card: target };
  }

  m = orig.match(/^(?:find|go to|goto|focus|jump to|where is|where'?s)\s+(.+)$/i);
  if (m) return { type: 'find', card: clean(m[1]) };

  return { type: 'unknown', text: raw };
}
import {
  addCard, addColumn, deleteCard, doingColumn, doneColumn, locate, moveCard, peopleOn, updateCard,
} from './board';
import type { Command } from './commands';
import { parseDue } from './dates';
import { boardSummary, cardDetails, columnReport, dueReport, mineReport, positionText, whoLabel } from './describe';
import { findCard, findColumn, findPerson, type MatchResult } from './match';
import type { Board, Card, Column } from './types';

export interface ExecContext {
  today: Date;
  me: string | null;
}

export interface ExecResult {
  ok: boolean;
  /** Spoken and shown to the user. */
  message: string;
  /** New board state, when the command changed something. */
  board?: Board;
  /** Short description used for undo ("Undid: moved …"). */
  label?: string;
  /** Card that should receive keyboard focus afterwards. */
  focusCardId?: string;
  /** Something the app itself must do. */
  effect?: 'undo' | 'redo' | 'help' | 'changes';
}

const quote = (s: string) => `“${s}”`;

function whichOne<T>(r: MatchResult<T>, name: (t: T) => string, what: string, query: string): string {
  if (r.ambiguous && r.candidates.length > 1) {
    const opts = r.candidates.slice(0, 3).map((c) => quote(name(c)));
    return `More than one ${what} matches ${quote(query)}: ${opts.join(' or ')}. Say a bit more of the name.`;
  }
  return `I couldn't find a ${what} called ${quote(query)}.`;
}

function resolveCard(board: Board, query: string): { card?: Card; error?: string } {
  const r = findCard(board, query);
  if (r.match) return { card: r.match };
  return { error: whichOne(r, (c) => c.title, 'card', query) };
}

function resolveColumn(board: Board, query: string): { column?: Column; error?: string } {
  const r = findColumn(board, query);
  if (r.match) return { column: r.match };
  const names = board.columns.map((c) => c.title).join(', ');
  return { error: `${whichOne(r, (c) => c.title, 'column', query)} Columns are: ${names}.` };
}

function moveTo(board: Board, card: Card, column: Column, position: 'top' | 'bottom' | undefined, ctx: ExecContext): ExecResult {
  const from = locate(board, card.id)!;
  const index = position === 'top' ? 0 : column.cardIds.filter((id) => id !== card.id).length;
  if (from.column.id === column.id && position === undefined) {
    return { ok: true, message: `${quote(card.title)} is already in ${column.title}.`, focusCardId: card.id };
  }
  const next = moveCard(board, card.id, column.id, index, ctx.me);
  const verb = from.column.id === column.id ? `Moved ${quote(card.title)} to the ${position}` : `Moved ${quote(card.title)} to ${column.title}`;
  return {
    ok: true,
    board: next,
    label: `${verb.replace(/^Moved/, 'move')}`,
    message: `${verb}. ${positionText(next, card.id)}.`,
    focusCardId: card.id,
  };
}

export function executeCommand(cmd: Command, board: Board, ctx: ExecContext): ExecResult {
  const { today, me } = ctx;
  switch (cmd.type) {
    case 'undo': return { ok: true, message: '', effect: 'undo' };
    case 'redo': return { ok: true, message: '', effect: 'redo' };
    case 'help': return { ok: true, message: '', effect: 'help' };
    case 'changes': return { ok: true, message: '', effect: 'changes' };
    case 'summary': return { ok: true, message: boardSummary(board, today, me) };
    case 'mine': return { ok: true, message: mineReport(board, today, me) };
    case 'whatsDue': return { ok: true, message: dueReport(board, cmd.range, today, me) };

    case 'add': {
      let column = board.columns[0];
      if (cmd.column) {
        const r = resolveColumn(board, cmd.column);
        if (!r.column) return { ok: false, message: r.error! };
        column = r.column;
      }
      const due = cmd.due ? parseDue(cmd.due, today) : null;
      let assignee: string | null = null;
      if (cmd.assignee) assignee = findPerson(peopleOn(board), cmd.assignee, me) ?? cmd.assignee.replace(/^./, (c) => c.toUpperCase());
      const { board: next, cardId } = addCard(board, column.id, { title: cmd.title, due, assignee }, me);
      const details = cardDetails(next.cards[cardId], today, me);
      return {
        ok: true,
        board: next,
        label: `add ${quote(cmd.title)}`,
        message: `Added ${quote(cmd.title)} to ${column.title}${details ? `, ${details}` : ''}.`,
        focusCardId: cardId,
      };
    }

    case 'addColumn': {
      const { board: next } = addColumn(board, cmd.title);
      return { ok: true, board: next, label: `add column ${quote(cmd.title)}`, message: `Added a column called ${quote(cmd.title)} at the end.` };
    }

    case 'move': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      let column = locate(board, c.card.id)!.column;
      if (cmd.column) {
        const r = resolveColumn(board, cmd.column);
        if (!r.column) return { ok: false, message: r.error! };
        column = r.column;
      }
      return moveTo(board, c.card, column, cmd.position, ctx);
    }

    case 'nudge': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      const loc = locate(board, c.card.id)!;
      const to = loc.index + (cmd.direction === 'up' ? -1 : 1);
      if (to < 0 || to >= loc.column.cardIds.length) {
        return { ok: true, message: `${quote(c.card.title)} is already at the ${cmd.direction === 'up' ? 'top' : 'bottom'} of ${loc.column.title}.`, focusCardId: c.card.id };
      }
      const next = moveCard(board, c.card.id, loc.column.id, to, me);
      return { ok: true, board: next, label: `move ${quote(c.card.title)} ${cmd.direction}`, message: `Moved ${cmd.direction}. ${positionText(next, c.card.id)}.`, focusCardId: c.card.id };
    }

    case 'done':
    case 'start': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      const column = cmd.type === 'done' ? doneColumn(board) : doingColumn(board);
      if (!column) return { ok: false, message: 'This board has no columns.' };
      return moveTo(board, c.card, column, undefined, ctx);
    }

    case 'delete': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      const loc = locate(board, c.card.id)!;
      const next = deleteCard(board, c.card.id);
      const neighbour = loc.column.cardIds[loc.index + 1] ?? loc.column.cardIds[loc.index - 1];
      return {
        ok: true,
        board: next,
        label: `delete ${quote(c.card.title)}`,
        message: `Deleted ${quote(c.card.title)} from ${loc.column.title}. Say “undo” or press Control Z to bring it back.`,
        focusCardId: neighbour,
      };
    }

    case 'rename': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      const next = updateCard(board, c.card.id, { title: cmd.title }, me);
      return { ok: true, board: next, label: `rename ${quote(c.card.title)}`, message: `Renamed ${quote(c.card.title)} to ${quote(cmd.title)}.`, focusCardId: c.card.id };
    }

    case 'due': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      const next = updateCard(board, c.card.id, { due: cmd.due }, me);
      const msg = cmd.due ? `${quote(c.card.title)} is now ${cardDetails({ ...next.cards[c.card.id], assignee: null, notes: '' }, today, me)}.` : `Removed the due date from ${quote(c.card.title)}.`;
      return { ok: true, board: next, label: `change the due date of ${quote(c.card.title)}`, message: msg, focusCardId: c.card.id };
    }

    case 'assign': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      let person: string | null = null;
      if (cmd.person) {
        person = findPerson(peopleOn(board), cmd.person, me);
        if (!person) {
          if (/^(me|myself|i)$/i.test(cmd.person)) return { ok: false, message: 'Set your name in Settings first, so Handrail knows who “me” is.' };
          person = cmd.person.replace(/^./, (ch) => ch.toUpperCase());
        }
      }
      const next = updateCard(board, c.card.id, { assignee: person }, me);
      const msg = person ? `Assigned ${quote(c.card.title)} to ${whoLabel(person, me)}.` : `${quote(c.card.title)} is no longer assigned to anyone.`;
      return { ok: true, board: next, label: `assign ${quote(c.card.title)}`, message: msg, focusCardId: c.card.id };
    }

    case 'note': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      const notes = c.card.notes.trim() ? `${c.card.notes.trim()}\n${cmd.text}` : cmd.text;
      const next = updateCard(board, c.card.id, { notes }, me);
      return { ok: true, board: next, label: `add a note to ${quote(c.card.title)}`, message: `Added a note to ${quote(c.card.title)}.`, focusCardId: c.card.id };
    }

    case 'read': {
      const r = resolveColumn(board, cmd.target);
      if (!r.column) return { ok: false, message: r.error! };
      return { ok: true, message: columnReport(board, r.column, today, me), focusCardId: r.column.cardIds[0] };
    }

    case 'readCard':
    case 'find': {
      const c = resolveCard(board, cmd.card);
      if (!c.card) return { ok: false, message: c.error! };
      const details = cardDetails(c.card, today, me);
      const notes = cmd.type === 'readCard' && c.card.notes.trim() ? ` Notes: ${c.card.notes.trim()}` : '';
      return {
        ok: true,
        message: `${c.card.title}${details ? `, ${details.replace(', has notes', '')}` : ''}. In ${positionText(board, c.card.id)}.${notes}`,
        focusCardId: c.card.id,
      };
    }

    case 'unknown':
    default:
      return {
        ok: false,
        message: `Sorry, I didn't understand ${quote((cmd as { text: string }).text)}. Try “add essay outline due friday”, “move lab report to done”, or say “help”.`,
      };
  }
}

# Handrail

**A project board that tells you what changed, so you never have to hunt for it, with or without sight.**

**Try it:** https://dakshhhhh-ops.github.io/Handrail/ (no account; it opens with a sample group project. Click the board name and choose *Simulate teammates' changes* to see the main feature.)

![The board with an Activity panel listing four changes since you last looked, one marked "for you", and the changed cards tagged on the board](docs/changes.png)

## The problem

In a group project, the hard part is often not doing your own task. It is **finding out what everyone else changed** since you last looked. On Trello, Notion or Jira you find out by scanning: you glance across the columns and notice that "Slides" moved to Done, or that a new card has your name on it. Activity feeds exist, but they are long lists of raw events, and written summaries are a paid AI add-on. Scanning is slow for everyone, and for a screen-reader user it means stepping through every card in every column to spot one difference.

Handrail does the scanning for you. When a teammate sends their link, it writes every change as a plain sentence, puts the ones that involve you first, and tags those cards on the board. It's free, private and screen-reader-first.

Moving cards without a mouse is not new (GitHub Projects and Jira support keyboard moves). Handrail includes it because the same people who can't scan a board often can't drag one either:

- **Blind and low-vision students**, who use screen readers or magnifiers.
- **Students with motor impairments** (tremor, RSI, one-handed use) who can't hold a mouse button steady while dragging.
- **Keyboard-only and voice-control users.**

WCAG 2.2 covers this in [2.5.7 Dragging Movements](https://www.w3.org/WAI/WCAG22/Understanding/dragging-movements.html): anything done by dragging must also be possible without dragging.

**Handrail's user:** Priya, a blind student working with NVDA on a group project. Her teammates Riya and Arjun use the board with a mouse.

## What it does

| Instead of… | In Handrail you… |
|---|---|
| Scanning the board for changes | Open your teammate's link and see or hear **"Since you last looked: Riya assigned 'Email Dr. Mehta' to you. Arjun moved 'Write the script' to Doing…"**. Changes that involve you come first, and changed cards are tagged on the board ("Riya · moved") |
| Dragging a card | Type or say **"move find sources to doing"** (Handrail shows what it will do before you press Enter), press a **number key** (3 sends it to column 3), or **pick it up with Space** and move it with the arrow keys |
| Reading every card to find deadlines | Ask **"what's due this week"**, **"anything overdue"** or **"my tasks"**, or press **Just mine** to see only your cards and the changes that involve you |
| Fiddly date pickers | Type **"due next friday"**, **"in 3 days"** or **"oct 30"** |
| Hoping you didn't break something | **Undo** any change with Ctrl+Z, the Undo button, or by saying "undo" |

### Built for many ways of working

- **Screen readers:** every card has a full spoken name ("Draft the outline, overdue by 1 day, assigned to you, has notes. 1 of 1 in Doing"). Every action is confirmed through a live region. Dialogs are native `<dialog>` elements, so focus is trapped and returned properly.
- **Keyboard:** one tab stop for the whole board, arrow-key navigation between cards, single-key shortcuts, and skip links. See the keyboard table under Help.
- **Voice:** a Speak button, in browsers with speech recognition (Chrome, Edge). Card-name matching tolerates recognition slips: "lab raport" still finds "Lab report".
- **Low vision and dyslexia:** high-contrast theme, text up to 200%, Atkinson Hyperlegible or OpenDyslexic fonts, relaxed spacing, a stacked layout for screen magnifiers, and replies read aloud for people who don't use a screen reader.
- **Mouse users:** normal drag-and-drop still works, so mixed groups can share one board.
- **Groups already on Trello:** import a Trello JSON export or a CSV. Export as a backup, CSV or plain text.

| Command box | Keyboard pick-up | Action menu instead of dragging |
|---|---|---|
| ![Command box replying "Moved to Doing"](docs/command.png) | ![A picked-up card with a dashed outline and key hints](docs/keyboard.png) | ![Card action menu with Move to, Order and Card buttons](docs/menu.png) |

| High contrast, 125% text | Phone, dark mode |
|---|---|
| ![Board in the high-contrast theme with larger text](docs/contrast.png) | ![Board on a phone in dark mode, columns stacked](docs/phone.png) |

## How sharing works (no server)

Handrail has no backend and no accounts. **Share** packs the whole board into a compressed link (`#board=…`). The part after `#` is never sent to a web server.

1. Priya shares the link in the group chat.
2. Riya opens it, makes changes, and shares her link back.
3. Priya opens Riya's link. Handrail compares it with the version Priya last saw and turns every difference into a sentence, naming who made it. It moves focus to that list and announces how many changes there are.

To see it without two devices, click the board name to open the board menu, then choose **Simulate teammates' changes**.

## Keyboard

| Key (on a card) | Action |
|---|---|
| Arrow keys | Move between cards |
| Enter | Action menu (move to a column, reorder, edit, delete) |
| Space | Pick up. Then arrows move it, Enter drops it, Escape cancels |
| 1–9 | Send to that column |
| Alt + arrows | Move one step without picking up |
| E / I / N / Delete | Edit / read details / new card here / delete |
| `/` · `?` · Ctrl+Z · Ctrl+Y | Command box · help · undo · redo |

## Run it locally

```bash
npm install
npm run dev          # http://localhost:5173
npm test             # 68 unit tests (parser, previews, dates, change detection, imports)
npm run test:e2e     # 31 browser tests incl. axe accessibility audit
npm run build        # static site in dist/
```

Every push to `main` runs type-checking, both test suites, and then deploys to GitHub Pages ([workflow](.github/workflows/deploy.yml)).

## How it's built

- **React 18 + TypeScript + Vite**, a static site with no backend.
- `src/model/` is plain TypeScript with no UI code, so it is unit-tested:
  - `commands.ts` reads plain-language commands with no AI service. It's offline, instant, private and predictable. It handles card titles that themselves contain "to" or "for" by only treating a trailing clause as a column or person when one with that name exists.
  - `match.ts` matches card and column names with fuzzy scoring and edit distance. Columns also match by synonym ("finished" means Done) or number. When two cards match equally well, it asks which one instead of guessing.
  - `dates.ts` handles everyday dates ("next friday", "the 30th", "in two weeks").
  - `diff.ts` compares two versions of a board and describes each change as a sentence, with changes that involve you first.
  - `validate.ts` treats every shared link, imported file and saved board as untrusted: it limits sizes, fixes ids and drops broken cards.
- **Testing:** Vitest (68 tests) and Playwright (31 tests), including a two-person handoff test that uses two separate browser contexts. **axe-core** checks WCAG 2.2 AA in light, dark and high-contrast themes, every dialog, and phone width, with zero violations.

## Limitations

- **Not yet tested with blind or motor-impaired users.** The design follows WCAG 2.2, the WAI-ARIA Authoring Practices and published guidance on accessible drag-and-drop, and the automated audit passes. That is not the same as real users saying it works. The next step is sessions with screen-reader users.
- **Screen readers in browse mode** pass single-letter keys to the screen reader instead of the page. Enter on a card (action menu) and the command box always work. Help explains this.
- **Sharing is by link, not live sync.** If two people edit at the same time, opening one person's link replaces your copy (you can undo). A small sync server is the obvious next step.
- **Voice input** depends on the browser's speech recognition (Chrome and Edge, online). Typing commands works everywhere.
- **English only** for commands and dates.

## Privacy

Boards are saved in your browser's local storage on your device. Nothing is sent anywhere unless you share a link yourself. There is no analytics.

