test.afterAll(() => { console.log('CONSOLE:', errors.length ? errors.join('\n') : 'none'); });

async function setSettings(page: Page, patch: Record<string, unknown>) {
  await page.evaluate((p) => {
    const raw = JSON.parse(localStorage.getItem('handrail:v1')!);
    raw.settings = { ...raw.settings, ...p };
    localStorage.setItem('handrail:v1', JSON.stringify(raw));
  }, patch);
  await page.reload();
  await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
}
async function simulate(page: Page) {
