  await page.getByRole('button', { name: 'Simulate teammates’ changes' }).click();
  await expect(page.getByTestId('change-list')).toBeVisible();
}
async function axe(page: Page, label: string) {
  const r = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa', 'best-practice']).analyze();
  const v = r.violations.map((x) => `${x.id} (${x.impact}): ${x.nodes.slice(0, 3).map((n) => n.target.join(' ')).join(' | ')}`);
  console.log(`AXE ${label}: ${v.length ? '\n  ' + v.join('\n  ') : 'clean'}`);
  return v;
}
const overflow = (page: Page) => page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);

// Is the focused element at least partly visible (not fully covered by sticky/fixed UI)?
const focusObscured = (page: Page) => page.evaluate(() => {
  const el = document.activeElement as HTMLElement | null;
  if (!el || el === document.body) return 'no focus';
  const r = el.getBoundingClientRect();
  if (r.bottom < 0 || r.top > innerHeight || r.right < 0 || r.left > innerWidth) return `offscreen ${el.id || el.className}`;
  const pts = [[0.5, 0.5], [0.15, 0.2], [0.85, 0.2], [0.15, 0.8], [0.85, 0.8]];
  const visible = pts.some(([fx, fy]) => {
    const x = r.left + r.width * fx, y = r.top + r.height * fy;
    if (x < 0 || y < 0 || x > innerWidth || y > innerHeight) return false;
    const hit = document.elementFromPoint(x, y);
    return !!hit && (hit === el || el.contains(hit));
  });
  return visible ? 'ok' : `OBSCURED ${el.id || el.getAttribute('aria-label')?.slice(0, 40) || el.className}`;
});

