const overflow = (page: Page) => page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);

// Is the focused element at least partly visible (not fully covered by sticky/fixed UI)?
const focusObscured = (page: Page) => page.evaluate(() => {
  const el = document.activeElement as HTMLElement | null;
  if (!el || el === document.body) return 'no focus';
  const r = el.getBoundingClientRect();
  const name = el.id || el.getAttribute('aria-label')?.slice(0, 40) || String(el.className);
  if (r.bottom < 0 || r.top > innerHeight || r.right < 0 || r.left > innerWidth) return `offscreen ${name}`;
  const pts = [[0.5, 0.5], [0.15, 0.2], [0.85, 0.2], [0.15, 0.8], [0.85, 0.8]];
