import { expect, test, type Page } from '@playwright/test';

async function setSettings(page: Page, patch: Record<string, unknown>) {
  await page.evaluate((p) => {
    const raw = JSON.parse(localStorage.getItem('handrail:v1')!);
    raw.settings = { ...raw.settings, ...p };
    localStorage.setItem('handrail:v1', JSON.stringify(raw));
  }, patch);
  await page.reload();
  await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
}
async function simulate(page: Page) {
  await page.locator('#board-switcher').click();
  await page.getByRole('button', { name: 'Simulate teammates’ changes' }).click();
  await expect(page.getByTestId('change-list')).toBeVisible();
}
const desc = (sel: string) => `(() => { const el = ${sel}; if (!el) return 'none'; return el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + (typeof el.className === 'string' && el.className ? '.' + el.className.trim().split(/\\s+/).join('.') : ''); })()`;

test.beforeEach(async ({ page }) => {
  await page.goto('/');
  await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
});

test('which elements overflow sideways at 200% text', async ({ page }) => {
  await setSettings(page, { textSize: 200 });
  for (const w of [320, 768, 1280]) {
    await page.setViewportSize({ width: w, height: 800 });
    const culprits = await page.evaluate((vw) => {
      const out: string[] = [];
      for (const el of document.querySelectorAll<HTMLElement>('body *')) {
        const r = el.getBoundingClientRect();
        if (r.right > vw + 1 && r.width > 0) {
          // Skip descendants of a horizontally scrolling container (the board is allowed to scroll).
          let p = el.parentElement; let inScroller = false;
          while (p) { const o = getComputedStyle(p).overflowX; if (o === 'auto' || o === 'scroll') { inScroller = true; break; } p = p.parentElement; }
          if (!inScroller) out.push(`${el.tagName.toLowerCase()}${el.id ? '#' + el.id : ''}.${String(el.className).split(' ').join('.')} right=${Math.round(r.right)} w=${Math.round(r.width)}`);
        }
      }
      return out.slice(0, 8);
    }, w);
    console.log(`OVERFLOW ${w}px:\n  ${culprits.join('\n  ') || 'none'}`);
  }
});

test('phone: what covers focused cards', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 700 });
  await simulate(page);
  if (await page.getByRole('dialog').isVisible().catch(() => false)) await page.keyboard.press('Escape');
  for (const id of ['k-rehearse', 'k-topic']) {
    const card = page.locator(`#card-${id}`);
    if (!(await card.count())) { console.log('missing', id); continue; }
    await card.focus();
    // Simulate how the app moves focus: focus() + scrollIntoView nearest.
    const r = await page.evaluate(([cid]) => {
      const el = document.getElementById(`card-${cid}`)!;
      el.scrollIntoView({ block: 'nearest' });
      const b = el.getBoundingClientRect();
      const hit = document.elementFromPoint(b.left + b.width / 2, b.top + b.height / 2) as HTMLElement | null;
      let cover = hit; while (cover && getComputedStyle(cover).position !== 'fixed' && getComputedStyle(cover).position !== 'sticky') cover = cover.parentElement;
      return { cardTop: Math.round(b.top), cardBottom: Math.round(b.bottom), vh: innerHeight, hit: hit ? `${hit.tagName}.${hit.className}` : null, cover: cover ? `${cover.tagName}.${cover.className} top=${Math.round(cover.getBoundingClientRect().top)}` : null };
    }, [id]);
    console.log(`COVER ${id}: ${JSON.stringify(r)}`);
  }
  const sp = await page.evaluate(() => getComputedStyle(document.documentElement).scrollPaddingBottom);
  console.log('html scroll-padding-bottom:', sp);
});

test('phone: focus after closing Activity, by keyboard and by mouse', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 700 });
  const btn = page.getByRole('button', { name: /^Activity/ }).first();
  console.log('Activity button name:', await btn.getAttribute('aria-label') ?? await btn.textContent());
  await btn.focus();
  await page.keyboard.press('Enter');
  await expect(page.getByRole('dialog')).toBeVisible();
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
  console.log('after keyboard open+Escape, focus on:', await page.evaluate(desc('document.activeElement')));
  await btn.click();
  await expect(page.getByRole('dialog')).toBeVisible();
  await page.getByRole('dialog').getByRole('button', { name: 'Close' }).click();
  await page.waitForTimeout(200);
  console.log('after mouse open + Close button, focus on:', await page.evaluate(desc('document.activeElement')));

  // Opened automatically by a teammate's changes:
  await simulate(page);
  console.log('after simulate, dialog open?', await page.getByRole('dialog').isVisible());
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
  console.log('after simulate + Escape, focus on:', await page.evaluate(desc('document.activeElement')));
});

test('desktop tab order from the top of a fresh page', async ({ page }) => {
  await simulate(page);
  await page.evaluate(() => { (document.activeElement as HTMLElement)?.blur(); scrollTo(0, 0); });
  await page.locator('body').click({ position: { x: 1, y: 1 } });
  const order: string[] = [];
  for (let i = 0; i < 40; i++) {
    await page.keyboard.press('Tab');
    order.push(await page.evaluate(() => {
      const el = document.activeElement as HTMLElement;
      const r = el.getBoundingClientRect();
      return `${(el.getAttribute('aria-label') || el.textContent || el.id).trim().slice(0, 28)} @(${Math.round(r.left)},${Math.round(r.top)})`;
    }));
  }
  console.log('TAB ORDER:\n  ' + order.join('\n  '));
});

