     1	/**
     2	 * Live sessions: teammates on the same board see each other's changes as they
     3	 * happen, with no Handrail server. Browsers find each other through public
     4	 * Nostr relays (signalling only, encrypted with the room password) and then
     5	 * talk directly over WebRTC data channels.
     6	 *
     7	 * Because boards are CRDT documents, the protocol is tiny: say hello with your
     8	 * name, send your whole document when someone joins, and send it again after
     9	 * each of your own edits. Every receiver merges; order and duplicates don't
    10	 * matter. A document that brings nothing new is ignored, so peers never echo.
    11	 */
    12	import { validateDoc, type Doc, type VersionVector } from '../model/crdt';
    13	import LZString from 'lz-string';
    14	
    15	export interface Transport {
    16	  /** Sends to everyone, or to one peer. */
    17	  send(channel: 'hello' | 'doc', data: string, to?: string): void;
    18	  onMessage(fn: (channel: 'hello' | 'doc', data: string, from: string) => void): void;
    19	  onJoin(fn: (peer: string) => void): void;
    20	  onLeave(fn: (peer: string) => void): void;
    21	  leave(): void;
    22	}
    23	
    24	export interface LivePeer {
    25	  id: string;
    26	  name: string | null;
    27	}
    28	
    29	export interface LiveCallbacks {
    30	  /** Latest local document (read when a peer joins). */
    31	  getDoc: () => Doc;
    32	  /** A peer sent a document that contains something new. */
    33	  onDoc: (doc: Doc, from: LivePeer) => void;
    34	  onPeers: (peers: LivePeer[]) => void;
    35	}
    36	
    37	/** True when `a` has seen every write `b` has (so merging b changes nothing). */
    38	export function covers(a: VersionVector, b: VersionVector): boolean {
    39	  return Object.entries(b).every(([actor, c]) => (a[actor] ?? 0) >= c);
    40	}
    41	
    42	export const packDoc = (doc: Doc) => LZString.compressToUTF16(JSON.stringify(doc));
    43	export function unpackDoc(data: string): Doc | null {
    44	  try {
    45	    const json = LZString.decompressFromUTF16(data);
    46	    return json ? validateDoc(JSON.parse(json)) : null;
    47	  } catch {
    48	    return null;
    49	  }
    50	}
    51	
    52	export interface LiveSession {
    53	  /** Call after every local edit. */
    54	  publish(doc: Doc): void;
    55	  setName(name: string | null): void;
    56	  peers(): LivePeer[];
    57	  leave(): void;
    58	}
    59	
    60	export function createSession(transport: Transport, name: string | null, cb: LiveCallbacks): LiveSession {
    61	  const peers = new Map<string, LivePeer>();
    62	  let myName = name;
    63	  let known: VersionVector = { ...cb.getDoc().vv };
    64	  const emit = () => cb.onPeers([...peers.values()]);
    65	
    66	  transport.onJoin((id) => {
    67	    peers.set(id, peers.get(id) ?? { id, name: null });
    68	    emit();
    69	    transport.send('hello', JSON.stringify({ name: myName }), id);
    70	    transport.send('doc', packDoc(cb.getDoc()), id);
    71	  });
    72	  transport.onLeave((id) => {
    73	    peers.delete(id);
    74	    emit();
    75	  });
    76	  transport.onMessage((channel, data, from) => {
    77	    const peer = peers.get(from) ?? { id: from, name: null };
    78	    peers.set(from, peer);
    79	    if (channel === 'hello') {
    80	      try {
    81	        const n = (JSON.parse(data) as { name?: unknown }).name;
    82	        peer.name = typeof n === 'string' ? n.slice(0, 60) : null;
    83	      } catch {
    84	        /* ignore */
    85	      }
    86	      emit();
    87	      return;
    88	    }
    89	    if (data.length > 2_000_000) return;
    90	    const doc = unpackDoc(data);
    91	    if (!doc || doc.id !== cb.getDoc().id) return;
    92	    if (covers(known, doc.vv)) return; // nothing new: never echo
    93	    known = mergeVV(known, doc.vv);
    94	    cb.onDoc(doc, peer);
    95	  });
    96	
    97	  return {
    98	    publish(doc) {
    99	      if (covers(known, doc.vv)) return;
   100	      known = mergeVV(known, doc.vv);
   101	      if (peers.size) transport.send('doc', packDoc(doc));
   102	    },
   103	    setName(n) {
   104	      myName = n;
   105	      transport.send('hello', JSON.stringify({ name: n }));
   106	    },
   107	    peers: () => [...peers.values()],
   108	    leave: () => transport.leave(),
   109	  };
   110	}
   111	
   112	function mergeVV(a: VersionVector, b: VersionVector): VersionVector {
   113	  const out = { ...a };
   114	  for (const [k, v] of Object.entries(b)) out[k] = Math.max(out[k] ?? 0, v);
   115	  return out;
   116	}
   117	
   118	/** Real network transport: Trystero over Nostr relays, loaded only when a session starts. */
   119	export async function trysteroTransport(boardId: string, room: string): Promise<Transport> {
   120	  const { joinRoom } = await import('trystero/nostr');
   121	  const r = joinRoom({ appId: 'handrail-live-v1', password: room }, `${boardId}:${room}`);
   122	  const [sendHello, getHello] = r.makeAction<string>('hello');
   123	  const [sendDoc, getDoc] = r.makeAction<string>('doc');
   124	  const handlers: ((c: 'hello' | 'doc', d: string, from: string) => void)[] = [];
   125	  getHello((d, from) => handlers.forEach((h) => h('hello', d, from)));
   126	  getDoc((d, from) => handlers.forEach((h) => h('doc', d, from)));
   127	  return {
   128	    send: (channel, data, to) => void (channel === 'hello' ? sendHello : sendDoc)(data, to ?? null),
   129	    onMessage: (fn) => handlers.push(fn),
   130	    onJoin: (fn) => r.onPeerJoin(fn),
   131	    onLeave: (fn) => r.onPeerLeave(fn),
   132	    leave: () => void r.leave(),
   133	  };
   134	}
   135	
   136	/** A random, unguessable room code (also the encryption password for signalling). */
   137	export function newRoomCode(): string {
   138	  const bytes = new Uint8Array(12);
   139	  crypto.getRandomValues(bytes);
   140	  return Array.from(bytes, (b) => 'abcdefghijkmnpqrstuvwxyz23456789'[b % 32]).join('');
   141	}
