import { addCard, deleteCard, moveCard, updateCard, locate } from '../qa/src/model/board';
import { commit, docFromBoard, materialize, mergeDocs } from '../qa/src/model/crdt';
import { revertEdit } from '../qa/src/model/revert';
import { demoBoard } from '../qa/src/model/seed';

const today = new Date(2026, 9, 22);
const colOf = (b: ReturnType<typeof materialize>, id: string) => locate(b, id)?.column.id ?? 'gone';

it('U1 undo my own move after merging a teammate link keeps all of the teammate work', () => {
  const base = docFromBoard(demoBoard(today), 'dpriya', 'Priya');
  // Priya's own action, recorded the way the store records it.
  const before = materialize(base);
  const after = moveCard(before, 'k-sources', 'c-done', 0, 'Priya');
  const mine = commit(base, after, 'dpriya', 'Priya');
  // Riya, concurrently: add a card, delete k-email, rename k-slides.
  let rv = materialize(base);
  rv = addCard(rv, 'c-todo', { title: 'Riya new card' }, 'Riya').board;
  rv = deleteCard(rv, 'k-email');
  rv = updateCard(rv, 'k-slides', { title: 'Slides 4-12' }, 'Riya');
  const riya = commit(base, rv, 'driya', 'Riya');
  const merged = mergeDocs(mine, riya);
  const { board } = revertEdit(materialize(merged), before, after, 'Priya');
  const undone = commit(merged, board, 'dpriya', 'Priya');
  const b = materialize(undone);
  const res = {
    riyaCard: Object.values(b.cards).some((c) => c.title === 'Riya new card'),
    emailStillDeleted: !b.cards['k-email'],
    slidesRenamed: b.cards['k-slides']?.title,
    sourcesBackInTodo: colOf(b, 'k-sources'),
  };
  console.log('U1', JSON.stringify(res));
  const riyaSide = materialize(mergeDocs(riya, undone));
  console.log('U1 riya side', JSON.stringify({ riyaCard: Object.values(riyaSide.cards).some((c) => c.title === 'Riya new card'), slides: riyaSide.cards['k-slides']?.title, sources: colOf(riyaSide, 'k-sources') }));
});

it('U2 undo a move that a teammate has since moved again does not fight them', () => {
  const base = docFromBoard(demoBoard(today), 'dpriya', 'Priya');
  const before = materialize(base);
  const after = moveCard(before, 'k-sources', 'c-done', 0, 'Priya');
  const mine = commit(base, after, 'dpriya', 'Priya');
  // Riya saw Priya's move and then moved the card to Doing.
  const riya = commit(mine, moveCard(materialize(mine), 'k-sources', 'c-doing', 0, 'Riya'), 'driya', 'Riya');
  const merged = mergeDocs(mine, riya);
  const r = revertEdit(materialize(merged), before, after, 'Priya');
  console.log('U2 card stays in', colOf(r.board, 'k-sources'), '| result:', JSON.stringify({ ...r, board: undefined }));
});

it('U3 undo then redo then merge', () => {
  const base = docFromBoard(demoBoard(today), 'dpriya', 'Priya');
  const before = materialize(base);
  const after = updateCard(before, 'k-topic', { title: 'Heat waves' }, 'Priya');
  let doc = commit(base, after, 'dpriya', 'Priya');
  doc = commit(doc, revertEdit(materialize(doc), before, after, 'Priya').board, 'dpriya', 'Priya');
  const t1 = materialize(doc).cards['k-topic'].title;
  doc = commit(doc, revertEdit(materialize(doc), after, before, 'Priya').board, 'dpriya', 'Priya');
  const t2 = materialize(doc).cards['k-topic'].title;
  const riya = commit(base, updateCard(materialize(base), 'k-groupchat', { title: 'Group chat (WhatsApp)' }, 'Riya'), 'driya', 'Riya');
  const m = materialize(mergeDocs(doc, riya));
  console.log('U3', JSON.stringify({ afterUndo: t1, afterRedo: t2, merged: m.cards['k-topic'].title, riyaEdit: m.cards['k-groupchat'].title }));
});

it('U4 undo a delete brings the card back where it was', () => {
  const base = docFromBoard(demoBoard(today), 'dpriya', 'Priya');
  const before = materialize(base);
  const after = deleteCard(before, 'k-script');
  let doc = commit(base, after, 'dpriya', 'Priya');
  doc = commit(doc, revertEdit(materialize(doc), before, after, 'Priya').board, 'dpriya', 'Priya');
  const b = materialize(doc);
  console.log('U4', JSON.stringify({ back: !!b.cards['k-script'], col: colOf(b, 'k-script'), index: locate(b, 'k-script')?.index }));
});

