// Runs in the page: contrast of the focus ring of the active element against what is behind the ring.
const RING = () => {
  const parse = (c: string) => {
    const m = c.match(/rgba?\(([^)]+)\)/);
    if (!m) return null;
    const [r, g, b, a = '1'] = m[1].split(/[ ,/]+/).filter(Boolean);
    return { r: +r, g: +g, b: +b, a: +a };
  };
  const lum = ({ r, g, b }: { r: number; g: number; b: number }) => {
    const f = (v: number) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
  };
  const ratio = (a: any, b: any) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };
  const bgBehind = (el: Element | null) => {
    for (let p = el; p; p = p.parentElement) {
      const c = parse(getComputedStyle(p).backgroundColor);
      if (c && c.a > 0.5) return c;
    }
    return parse(getComputedStyle(document.body).backgroundColor) ?? { r: 255, g: 255, b: 255, a: 1 };
  };
  const el = document.activeElement as HTMLElement;
  if (!el || el === document.body) return null;
  const cs = getComputedStyle(el);
  const ring = parse(cs.outlineColor);
  const width = parseFloat(cs.outlineWidth);
  const offset = parseFloat(cs.outlineOffset);
  // An outline with offset > 0 sits on the parent's background; offset <= 0 sits over the element's own edge.
  const behind = offset > 0 ? bgBehind(el.parentElement) : bgBehind(el);
  const own = bgBehind(el);
  const name = (el.getAttribute('aria-label') || el.textContent || el.id || el.tagName).trim().replace(/\s+/g, ' ').slice(0, 32);
  if (cs.outlineStyle === 'none' || !ring || width < 1) return { name, ring: 'none', ratio: 0, vsOwn: 0 };
  return { name, ring: cs.outlineColor, width, offset, ratio: +ratio(ring, behind).toFixed(2), vsOwn: +ratio(ring, own).toFixed(2), behind: `rgb(${behind.r},${behind.g},${behind.b})` };
};

async function tabAll(page: Page, label: string, max = 70) {
  const bad: string[] = [];
  const seen = new Set<string>();
  let worst = 99;
  for (let i = 0; i < max; i++) {
    await page.keyboard.press('Tab');
    const r = await page.evaluate(RING);
    if (!r || seen.has(r.name)) continue;
    seen.add(r.name);
    worst = Math.min(worst, r.ratio);
    if (r.ratio < 3) bad.push(`${r.name} ring=${r.ring} on ${r.behind ?? '?'} ${r.ratio}:1`);
  }
  console.log(`RING ${label}: ${seen.size} stops, worst ${worst}:1${bad.length ? '\n    LOW: ' + bad.join('\n    LOW: ') : ''}`);
}

