test('selection box: handles and You tag are not clipped and cover nothing', async ({ page }) => {
  for (const [w, h] of [[1280, 800], [1024, 700], [375, 760]] as const) {
    await page.setViewportSize({ width: w, height: h });
    await page.goto('/');
    await simulate(page);
    if (await page.getByRole('dialog').isVisible().catch(() => false)) await page.keyboard.press('Escape');
    await page.locator('[data-card]').first().focus();
    await page.keyboard.press('ArrowUp'); // keyboard interaction so :focus-visible applies
    const issues = new Set<string>();
    for (let i = 0; i < 16; i++) {
      const r = await page.evaluate(() => {
        const card = document.activeElement as HTMLElement;
        if (!card?.matches('.card')) return [`focus not on a card: ${card?.className}`];
        const out: string[] = [];
        const cr = card.getBoundingClientRect();
        const after = getComputedStyle(card, '::after');
        const px = (v: string) => (v === 'auto' ? 0 : parseFloat(v));
        const box = after.content === 'none' ? null : {
          left: cr.left + px(after.left), top: cr.top + px(after.top),
          right: cr.right - px(after.right), bottom: cr.bottom - px(after.bottom),
        };
        const tag = card.querySelector('.focus-tag') as HTMLElement | null;
        const tr = tag && getComputedStyle(tag).display !== 'none' ? tag.getBoundingClientRect() : null;
        const shapes: [string, { left: number; top: number; right: number; bottom: number }][] = [];
        if (box) shapes.push(['handles', box]);
        if (tr) shapes.push(['You tag', tr]);
        if (!box) out.push('no ::after handles');
        if (!tr) out.push('no visible focus-tag');
        // Clipping by any overflow ancestor.
        for (const [n, s] of shapes) {
          for (let p = card.parentElement; p; p = p.parentElement) {
            const cs = getComputedStyle(p);
            if (cs.overflowX !== 'visible' || cs.overflowY !== 'visible') {
              const pr = p.getBoundingClientRect();
              const clipL = Math.max(0, pr.left - s.left), clipR = Math.max(0, s.right - pr.right);
              const clipT = Math.max(0, pr.top - s.top), clipB = Math.max(0, s.bottom - pr.bottom);
              if (clipL + clipR + clipT + clipB > 1) out.push(`${n} clipped by ${p.tagName}.${String(p.className).split(' ')[0]} (L${Math.round(clipL)} R${Math.round(clipR)} T${Math.round(clipT)} B${Math.round(clipB)})`);
              break;
            }
          }
        }
        // Overlap with other visible interactive elements.
        const others = [...document.querySelectorAll<HTMLElement>('button, a, input, [tabindex="0"]')].filter((o) => o !== card && !card.contains(o) && o.offsetParent);
        for (const [n, s] of shapes) {
          for (const o of others) {
            const or = o.getBoundingClientRect();
            const ix = Math.min(s.right, or.right) - Math.max(s.left, or.left);
            const iy = Math.min(s.bottom, or.bottom) - Math.max(s.top, or.top);
            if (ix > 2 && iy > 2) out.push(`${n} overlaps "${(o.getAttribute('aria-label') || o.textContent || '').trim().slice(0, 24)}" by ${Math.round(ix)}x${Math.round(iy)}`);
          }
        }
        return out.map((x) => `${card.id}: ${x}`);
      });
      r.forEach((x) => issues.add(x));
      await page.keyboard.press(i % 3 === 2 ? 'ArrowRight' : 'ArrowDown');
    }
