    });
    if (!vis) {
      const hit = document.elementFromPoint(r.left + r.width / 2, Math.min(Math.max(r.top + r.height / 2, 0), innerHeight - 1)) as HTMLElement | null;
      why.push(`covered by ${hit?.tagName}.${String(hit?.className).split(' ')[0]}`);
    }
  }
  return { name, ok: why.length === 0, why: why.join(', ') };
};

